#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_scribMode;
uniform float amzp_fillType;
uniform float amzp_edgeWidth;
layout(color) uniform half4 amzp_color;
uniform float amzp_opacity;
uniform float amzp_angle;
uniform float amzp_strokeWidth;
uniform float amzp_spacing;
uniform float amzp_spacingVar;
uniform float amzp_curviness;
uniform float amzp_start;
uniform float amzp_end;
uniform float amzp_wiggleType;
uniform float amzp_wiggles;
uniform float amzp_seed;
uniform float amzp_composite;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float h1(float x, float k) { return fract(sin(x * 127.1 + k * 311.7 + amzp_seed * 17.13) * 43758.5453); }
    float wig(float j, float k, float t) {
        if (int(amzp_wiggleType) == 0) return h1(j, k) * 2.0 - 1.0;
        float f = floor(t), g = fract(t);
        float a = h1(j + f * 13.0, k) * 2.0 - 1.0;
        if (int(amzp_wiggleType) == 1) return a;
        float b = h1(j + (f + 1.0) * 13.0, k) * 2.0 - 1.0;
        return mix(a, b, g * g * (3.0 - 2.0 * g));
    }
    float alphaAt(float2 px, float2 W) {
        return layerAt(float2(px.x / W.x + 0.5, 0.5 - px.y / W.y)).a;
    }
    float2 gW; float2 gDir; float2 gPer; float gHu; float gHv; float gSp; float gT; float gExt;
    bool inShape(float u, float v) { return alphaAt(gDir * u + gPer * v, gW) > 0.5; }
    float passV(float j) { return -gHv + (j + 0.5) * gSp + amzp_spacingVar * gSp * 0.5 * wig(j, 1.0, gT); }
    float2 spanOf(float j) {
        float v = passV(j);
        float st = 2.0 * gHu / 18.0;
        float uL = 1e5, uR = -1e5;
        for (int s = 0; s < 18; s++) {
            float u = -gHu + (float(s) + 0.5) * st;
            if (inShape(u, v)) { uL = min(uL, u); uR = max(uR, u); }
        }
        if (uL > uR) return float2(1.0, -1.0);
        float a = uL - st, b = uL;
        for (int r = 0; r < 4; r++) { float m = 0.5 * (a + b); if (inShape(m, v)) b = m; else a = m; }
        uL = b;
        a = uR; b = uR + st;
        for (int r = 0; r < 4; r++) { float m = 0.5 * (a + b); if (inShape(m, v)) a = m; else b = m; }
        uR = a;
        return float2(uL - gExt, uR + gExt);
    }
    float segD(float2 p, float2 a, float2 b) {
        float2 pa = p - a, ba = b - a;
        float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-4), 0.0, 1.0);
        return length(pa - ba * h);
    }
    float classicCover(float2 P, float2 W) {
        float an = radians(amzp_angle);
        float2 dir = float2(cos(an), sin(an));
        float2 per = float2(-dir.y, dir.x);
        float u = dot(P, dir), v = dot(P, per);
        float hu = 0.5 * (abs(W.x * dir.x) + abs(W.y * dir.y)) + amzp_edgeWidth;
        float hv = 0.5 * (abs(W.x * per.x) + abs(W.y * per.y)) + amzp_edgeWidth;
        float sp = max(amzp_spacing, 0.5);
        float uf = clamp((u + hu) / (2.0 * hu), 0.0, 1.0);
        float passes = floor(2.0 * hv / sp) + 2.0;
        float t = time * amzp_wiggles;
        float cover = 0.0;
        float sw = max(amzp_strokeWidth, 0.3) * 0.5;
        float jc = floor((v + hv) / sp - 0.5 * uf);
        for (int q = -2; q <= 2; q++) {
            float j = jc + float(q);
            if (j < 0.0 || j > passes) continue;
            bool even = mod(j, 2.0) < 0.5;
            float along = even ? uf : 1.0 - uf;
            float amzLocal_pos = (j + along) / (passes + 1.0);
            if (amzLocal_pos < amzp_start || amzLocal_pos > amzp_end) continue;
            float lv = -hv + j * sp + sp * along;
            lv += amzp_spacingVar * sp * 0.5 * wig(j, 1.0, t);
            float bend = amzp_curviness * sp * 1.2;
            lv += bend * sin(along * 6.2831853 * (1.0 + h1(j, 3.0)) + 6.2831853 * wig(j, 2.0, t));
            float d = abs(v - lv);
            cover = max(cover, 1.0 - smoothstep(sw - 0.7, sw + 0.7, d));
        }
        return cover;
    }
    void nmMain() {
        float2 W = layer;
        float2 P = (float2(amzLayerNorm().x, 1.0 - amzLayerNorm().y) - 0.5) * W;
        float4 orig = layerAt(amzLayerNorm());
        float a0 = orig.a;
        float m = 1.0;
        if (int(amzp_fillType) != 0) {
            float e = max(amzp_edgeWidth, 1.0) * (int(amzp_fillType) == 1 ? 0.5 : 1.0);
            float mn = a0, mx = a0;
            for (int i = 0; i < 12; i++) {
                float an = float(i) * 0.5235988;
                float2 d = float2(cos(an), sin(an));
                float s1 = alphaAt(P + d * e, W);
                float s2 = alphaAt(P + d * e * 0.5, W);
                mn = min(mn, min(s1, s2));
                mx = max(mx, max(s1, s2));
            }
            if (int(amzp_fillType) == 1) m = smoothstep(0.3, 0.7, mx) * (1.0 - smoothstep(0.3, 0.7, mn));
            else if (int(amzp_fillType) == 2) m = smoothstep(0.3, 0.7, a0) * (1.0 - smoothstep(0.3, 0.7, mn));
            else m = (1.0 - smoothstep(0.3, 0.7, a0)) * smoothstep(0.3, 0.7, mx);
        }
        if (int(amzp_scribMode) == 1) {
            if (int(amzp_fillType) == 0) m = smoothstep(0.3, 0.7, a0);
            float cc = classicCover(P, W);
            float kc = clamp(cc * m * amzp_opacity, 0.0, 1.0);
            float4 inkc = float4(amzp_color.rgb * kc, kc);
            if (int(amzp_composite) == 0) amzOutput = inkc;
            else if (int(amzp_composite) == 1) amzOutput = inkc + orig * (1.0 - inkc.a);
            else amzOutput = orig * clamp(cc * m, 0.0, 1.0) * amzp_opacity;
            return;
        }
        float an = radians(amzp_angle);
        gDir = float2(cos(an), sin(an));
        gPer = float2(-gDir.y, gDir.x);
        gW = W;
        gHu = 0.5 * (abs(W.x * gDir.x) + abs(W.y * gDir.y)) + amzp_edgeWidth;
        gHv = 0.5 * (abs(W.x * gPer.x) + abs(W.y * gPer.y)) + amzp_edgeWidth;
        gSp = max(amzp_spacing, 0.5);
        gT = time * amzp_wiggles;
        gExt = (int(amzp_fillType) == 1 || int(amzp_fillType) == 3) ? max(amzp_edgeWidth, 1.0) * (int(amzp_fillType) == 1 ? 0.5 : 1.0) : 0.0;
        float u = dot(P, gDir), v = dot(P, gPer);
        float passes = floor(2.0 * gHv / gSp) + 1.0;
        float sw = max(amzp_strokeWidth, 0.3) * 0.5;
        float bend = amzp_curviness * gSp * 1.2;
        float loopR = gSp * 0.55 + sw;
        float2 pq = float2(u, v);
        float jc = floor((v + gHv) / gSp - 0.5);
        float best = 1e5;
        float2 S0 = spanOf(jc - 2.0), S1 = spanOf(jc - 1.0), S2 = spanOf(jc), S3 = spanOf(jc + 1.0), S4 = spanOf(jc + 2.0), S5 = spanOf(jc + 3.0);
        for (int q = 0; q < 5; q++) {
            float j = jc - 2.0 + float(q);
            if (j < 0.0 || j >= passes) continue;
            float2 sj = q == 0 ? S0 : (q == 1 ? S1 : (q == 2 ? S2 : (q == 3 ? S3 : S4)));
            float2 sn = q == 0 ? S1 : (q == 1 ? S2 : (q == 2 ? S3 : (q == 3 ? S4 : S5)));
            bool even = mod(j, 2.0) < 0.5;
            float vj = passV(j);
            float vn = passV(j + 1.0);
            float pj = j / passes, pn = (j + 1.0) / passes;
            if (sj.x <= sj.y) {
                float len = max(sj.y - sj.x, 1e-3);
                float tl = clamp((u - sj.x) / len, 0.0, 1.0);
                float alongP = even ? tl : 1.0 - tl;
                float amzLocal_pos = pj + alongP * (pn - pj) * 0.85;
                if (amzLocal_pos >= amzp_start && amzLocal_pos <= amzp_end) {
                    float lv = vj + bend * sin(3.1415927 * tl) * sin(6.2831853 * (h1(j, 3.0) + wig(j, 2.0, gT) * 0.5));
                    float d = (u >= sj.x && u <= sj.y) ? abs(v - lv) : length(pq - float2(clamp(u, sj.x, sj.y), vj));
                    best = min(best, d);
                }
                if (j + 1.0 < passes && sn.x <= sn.y) {
                    float posT = pj + (pn - pj) * 0.925;
                    if (posT >= amzp_start && posT <= amzp_end) {
                        float ua = even ? sj.y : sj.x;
                        float ub = even ? sn.y : sn.x;
                        float uc = even ? max(ua, ub) + gSp * 0.55 : min(ua, ub) - gSp * 0.55;
                        float2 A = float2(ua, vj), B = float2(uc, 0.5 * (vj + vn)), C = float2(ub, vn);
                        float2 prev = A;
                        for (int k = 1; k <= 8; k++) {
                            float tt = float(k) / 8.0;
                            float2 pt = (1.0 - tt) * (1.0 - tt) * A + 2.0 * (1.0 - tt) * tt * B + tt * tt * C;
                            best = min(best, segD(pq, prev, pt));
                            prev = pt;
                        }
                    }
                }
            }
        }
        float cover = 1.0 - smoothstep(sw - 0.7, sw + 0.7, best);
        if (int(amzp_fillType) == 0) {
            float near = a0;
            for (int i = 0; i < 8; i++) {
                float a2 = float(i) * 0.7853982;
                near = max(near, alphaAt(P + float2(cos(a2), sin(a2)) * loopR, W));
            }
            m = smoothstep(0.2, 0.6, near);
        }
        float k = clamp(cover * m * amzp_opacity, 0.0, 1.0);
        float4 ink = float4(amzp_color.rgb * k, k);
        if (int(amzp_composite) == 0) amzOutput = ink;
        else if (int(amzp_composite) == 1) amzOutput = ink + orig * (1.0 - ink.a);
        else amzOutput = orig * clamp(cover * m, 0.0, 1.0) * amzp_opacity;
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
